import { AdminPage, NavigationComponent } from '../support/pages/';

describe('Admin User Management — Extended Coverage', () => {

  describe('@boundary — Search and Form Validation', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToAdmin();
    });

    // Feature: Search with no matching username returns empty table without error
    it('@boundary — Search for non-existent user shows empty table, not an error', () => {
      AdminPage
        .searchForUser('zzz_nonexistent_user_xyz')
        .clickSearch();

      // When 0 results, OrangeHRM hides .oxd-table-body and shows "No Records Found"
      cy.get('.oxd-table').should('be.visible');
      cy.get('body').should('not.contain', 'Error');
      cy.contains('No Records Found').should('be.visible');
    });

    // Feature: Reset button clears all search fields
    it('@boundary — Reset button clears all search filters and shows full list', () => {
      AdminPage
        .searchForUser('Admin')
        .clickSearch();

      // Verify some results then reset
      cy.get('.oxd-table-body').should('be.visible');
      AdminPage.clickReset();

      // After reset, the Username input should be empty
      cy.contains('.oxd-label', 'Username')
        .closest('.oxd-input-group')
        .find('input')
        .should('have.value', '');
    });
  });

  describe('@error — Add User Form Validation', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToAdmin();
    });

    // Feature: Add User form submitted empty shows required field errors
    it('@error — Save Add User form without any fields shows required field validation errors', () => {
      AdminPage.clickAdd();
      AdminPage.verifyAddUserPage();

      // Submit empty form
      cy.contains('button', 'Save').click();

      // User Role, Employee Name, Username, Password are required
      cy.get('.oxd-input-field-error-message').should('have.length.gte', 2);
      cy.get('.oxd-input-field-error-message').first().should('contain', 'Required');
    });

    // Feature: Duplicate username shows uniqueness error
    it('@error — Creating user with existing username "Admin" shows duplicate error', () => {
      AdminPage.clickAdd();
      AdminPage.verifyAddUserPage();

      cy.fixture('admin-crud').then((data) => {
        // Fill minimum required fields with a known-existing username
        cy.contains('.oxd-label', 'Username')
          .closest('.oxd-input-group')
          .find('input')
          .type(data.duplicateUser.username);

        cy.contains('button', 'Save').click();

        // OrangeHRM returns "Already exists" for duplicate usernames
        cy.get('.oxd-input-field-error-message, [role="alert"]')
          .should('contain.text', 'Already exists');
      });
    });

    // Feature: Password / Confirm Password mismatch
    it('@error — Mismatched Password and Confirm Password on Add User shows validation error', () => {
      AdminPage.clickAdd();
      AdminPage.verifyAddUserPage();

      cy.fixture('admin-crud').then((data) => {
        cy.contains('.oxd-label', 'Password')
          .closest('.oxd-input-group')
          .find('input')
          .type(data.mismatchedPasswords.password);

        cy.contains('.oxd-label', /^Confirm Password$/)
          .closest('.oxd-input-group')
          .find('input')
          .type(data.mismatchedPasswords.confirmPassword);

        cy.contains('button', 'Save').click();

        cy.get('.oxd-input-field-error-message')
          .should('contain.text', 'Passwords do not match');
      });
    });
  });

  describe('@security — Authorization and Input Safety', () => {
    // Feature: Unauthenticated user cannot access Admin module
    // KNOWN LIMITATION: opensource-demo.orangehrmlive.com is a fully open demo site.
    // It does not enforce server-side auth or client-side Vue router guards for direct URL
    // navigation — the admin page loads without credentials. This test is skipped in the
    // demo environment; enable it against a properly secured OrangeHRM instance.
    it('@security — [PENDING] Unauthenticated user accessing Admin is redirected to login', function () {
      this.skip();
    });

    // Feature: XSS payload in username search field is sanitized
    it('@security — XSS payload in Username search field is not executed', () => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToAdmin();

      cy.fixture('admin-crud').then((data) => {
        AdminPage.searchForUser(data.xssPayload);

        // Verify no alert dialog appears (XSS execution would trigger cy.on('window:alert'))
        cy.on('window:alert', () => {
          throw new Error('XSS payload was executed — alert dialog appeared');
        });

        AdminPage.clickSearch();
        // If we reach here, no alert was triggered
        cy.get('.oxd-table').should('be.visible');
      });
    });
  });

  describe('@state — User Account Status Changes', () => {
    // Feature: Disable a user account prevents login
    // NOTE: This test requires creating a temporary user — skipped in demo environment
    it('@state — [PENDING] Disabling a user account prevents them from logging in', function () {
      // Implementation requires:
      // 1. Create a test user via Admin UI or API
      // 2. Disable the user via Admin UI
      // 3. Attempt login as that user
      // 4. Verify "Account Disabled" or similar error
      // 5. Teardown: delete the test user
      this.skip();
    });

    // Feature: Deleting a user removes them from the System Users list
    it('@state — [PENDING] Deleting a user removes them from System Users list', function () {
      // Implementation requires creating a deletable test user first
      // Skipped in demo environment to avoid modifying shared data
      this.skip();
    });
  });

  describe('@contract — API and Pagination', () => {
    beforeEach(() => {
      cy.loginWithEnvCredentials();
      NavigationComponent.navigateToAdmin();
    });

    // Feature: User list API returns results — no 5xx error
    it('@contract — System Users list loads without API errors', () => {
      cy.intercept('GET', '**/viewSystemUser**').as('getUserList');

      NavigationComponent.navigateToAdmin();

      cy.wait('@getUserList').then((interception) => {
        expect(interception.response.statusCode).to.be.lessThan(500);
      });

      AdminPage.verifyTableVisible();
    });

    // Feature: Search API returns filtered results
    it('@contract — Username search API returns filtered results without 5xx error', () => {
      cy.fixture('admin-crud').then((data) => {
        // Intercept must be registered before the action that triggers it.
        // OrangeHRM's search fires a GET to /api/v2/admin/users or the page URL with query params.
        cy.intercept('GET', /viewSystemUser|\/api\/v2\/admin\/users/).as('searchUsers');

        AdminPage
          .searchForUser(data.searchCriteria.username)
          .clickSearch();

        cy.wait('@searchUsers', { timeout: 15000 }).then((interception) => {
          expect(interception.response.statusCode).to.be.lessThan(500);
        });

        AdminPage.verifySearchResults(data.searchCriteria.username);
      });
    });
  });
});
